LOAN_PAYMENT_AMOUNT: Decimal = Decimal("0.00")

def dti_calculation_C2() -> None:
    """Calculates the debt-to-income ratio."""
    global WS_CALC_RESULT, WS_NOT_APPROVED, CUST_TOTAL_BALANCE
    WS_CALC_RESULT = LOAN_PAYMENT_AMOUNT / (CUST_TOTAL_BALANCE / 12)
    if WS_CALC_RESULT > Decimal("0.43"):
        WS_NOT_APPROVED = True

CUST_TOTAL_BALANCE: Decimal = Decimal("0.00")

def ltv_calculation_C2() -> None:
    """Calculates the loan-to-value ratio."""
    global LOAN_LTV_RATIO, LOAN_CURRENT_BALANCE, LOAN_COLLATERAL_VALUE, WS_CALC_FEE
    LOAN_LTV_RATIO = LOAN_CURRENT_BALANCE / LOAN_COLLATERAL_VALUE
    if LOAN_LTV_RATIO > Decimal("0.80"):
        WS_CALC_FEE += WS_LOAN_ORIGINATION_PCT

LOAN_LTV_RATIO: Decimal = Decimal("0.00")
LOAN_CURRENT_BALANCE: Decimal = Decimal("0.00")
LOAN_COLLATERAL_VALUE: Decimal = Decimal("0.00")
WS_CALC_FEE: Decimal = Decimal("0.00")
WS_LOAN_ORIGINATION_PCT: Decimal = Decimal("0.00")

