def main_control_C5() -> None:
    """Main control."""
    initialization_C5()
    while WS_EOF_FLAG != 'Y':
        process_transactions_C5()
    finalization_C5()
    raise SystemExit

def initialization_C5() -> None:
    """Initialization."""
    global WS_WORK_AREAS, WS_COUNTERS, WS_TOTALS, WS_CURRENT_DATETIME
