    RPT_TRANSFERS  = None  # TODO: was WS_TOTAL_TRANSFERS
    RPT_NET_AMOUNT = WS_TOTAL_DEPOSITS - WS_TOTAL_WITHDRAWALS
    WS_REPORT_DETAIL = {"RPT_TRANS_COUNT": RPT_TRANS_COUNT, "RPT_DEPOSITS": RPT_DEPOSITS, "RPT_WITHDRAWALS": RPT_WITHDRAWALS, "RPT_TRANSFERS": RPT_TRANSFERS, "RPT_NET_AMOUNT": RPT_NET_AMOUNT}
    # Write report_record FROM ws_report_detail

