def loan_processing_C6() -> None:
    """Brief description."""
    validate_loan_application_C6()
    if WS_VALID_FLAG == "Y":
        calculate_credit_score_C6()
        assess_risk_C6()
        determine_approval_C6()
        if WS_APPROVAL_STATUS == "A":
            generate_loan_terms_C6()
            create_amortization_C6()
            finalize_loan_C6()
        else:
            process_decline_C6()

def validate_loan_application_C6() -> None:
    """Brief description."""
    WS_VALID_FLAG = "Y"
    # assuming loan_amount is accessible here, or within a LoanApplication object
    loan_amount: Decimal = Decimal("0.0")
    loan_term_months: int = 0

    if WS_LOAN_AMOUNT < 1000:
        WS_VALID_FLAG = "N"
        WS_ERROR_MSG = "MINIMUM LOAN AMOUNT IS $1000"
        return  # Simulate EXIT PARAGRAPH
    if WS_LOAN_AMOUNT > 10000000:
        WS_VALID_FLAG = "N"
        WS_ERROR_MSG = "MAXIMUM LOAN AMOUNT EXCEEDED"
        return  # Simulate EXIT PARAGRAPH
    if loan_term_months < 6 or loan_term_months > 360:
        WS_VALID_FLAG = "N"
        WS_ERROR_MSG = "INVALID LOAN TERM"

def calculate_credit_score_C6() -> None:
    """Brief description."""
    WS_CREDIT_SCORE = 0
    score_payment_history_C6()
    score_credit_utilization_C6()
    score_credit_length_C6()
    score_new_credit_C6()
    score_credit_mix_C6()
    determine_tier_C6()

def score_payment_history_C6() -> None:
    """Brief description."""
    WS_PAYMENT_SCORE = (
        (WS_ON_TIME_PAYMENTS * 100)
        / (
            WS_ON_TIME_PAYMENTS
            + WS_LATE_30_DAYS
            + WS_LATE_60_DAYS
            + WS_LATE_90_DAYS
        )
        if (WS_ON_TIME_PAYMENTS + WS_LATE_30_DAYS + WS_LATE_60_DAYS + WS_LATE_90_DAYS) > 0 else 0
    )
    WS_PAYMENT_SCORE = WS_PAYMENT_SCORE * Decimal("0.35")
    WS_CREDIT_SCORE += int(WS_PAYMENT_SCORE)

def score_credit_utilization_C6() -> None:
    """Brief description."""
    if WS_CREDIT_UTILIZATION <= 10:
        WS_UTIL_SCORE = 100
    elif WS_CREDIT_UTILIZATION <= 30:
        WS_UTIL_SCORE = 80
    elif WS_CREDIT_UTILIZATION <= 50:
        WS_UTIL_SCORE = 60
    elif WS_CREDIT_UTILIZATION <= 75:
        WS_UTIL_SCORE = 40
    else:
        WS_UTIL_SCORE = 20
    WS_UTIL_SCORE = WS_UTIL_SCORE * Decimal("0.30")
    WS_CREDIT_SCORE += int(WS_UTIL_SCORE)

def score_credit_length_C6() -> None:
    """Brief description."""
    if WS_CREDIT_HISTORY_LEN >= 84:
        WS_LENGTH_SCORE = 100
    elif WS_CREDIT_HISTORY_LEN >= 60:
        WS_LENGTH_SCORE = 80
    elif WS_CREDIT_HISTORY_LEN >= 36:
        WS_LENGTH_SCORE = 60
    elif WS_CREDIT_HISTORY_LEN >= 12:
        WS_LENGTH_SCORE = 40
    else:
        WS_LENGTH_SCORE = 20
    WS_LENGTH_SCORE = WS_LENGTH_SCORE * Decimal("0.15")
    WS_CREDIT_SCORE += int(WS_LENGTH_SCORE)

def score_new_credit_C6() -> None:
    """Brief description."""
    if WS_NEW_CREDIT_INQS == 0:
        WS_NEW_SCORE = 100
    elif WS_NEW_CREDIT_INQS <= 2:
        WS_NEW_SCORE = 80
    elif WS_NEW_CREDIT_INQS <= 4:
        WS_NEW_SCORE = 60
    elif WS_NEW_CREDIT_INQS <= 6:
        WS_NEW_SCORE = 40
    else:
        WS_NEW_SCORE = 20
    WS_NEW_SCORE = WS_NEW_SCORE * Decimal("0.10")
    WS_CREDIT_SCORE += int(WS_NEW_SCORE)

def score_credit_mix_C6() -> None:
    """Brief description."""
    if WS_CREDIT_MIX_SCORE >= 80:
        WS_MIX_SCORE = 100
    elif WS_CREDIT_MIX_SCORE >= 60:
        WS_MIX_SCORE = 80
    elif WS_CREDIT_MIX_SCORE >= 40:
        WS_MIX_SCORE = 60
    elif WS_CREDIT_MIX_SCORE >= 20:
        WS_MIX_SCORE = 40
    else:
        WS_MIX_SCORE = 20
    WS_MIX_SCORE = WS_MIX_SCORE * Decimal("0.10")
    WS_CREDIT_SCORE += int(WS_MIX_SCORE)

def determine_tier_C6() -> None:
    """Brief description."""
    if WS_CREDIT_SCORE >= 750:
        WS_CREDIT_TIER = "A"
    elif WS_CREDIT_SCORE >= 700:
        WS_CREDIT_TIER = "B"
    elif WS_CREDIT_SCORE >= 650:
        WS_CREDIT_TIER = "C"
    elif WS_CREDIT_SCORE >= 600:
        WS_CREDIT_TIER = "D"
    else:
        WS_CREDIT_TIER = "F"

def assess_risk_C6() -> None:
    """Brief description."""
    WS_RISK_SCORE = 0
    evaluate_dti_C6()
    evaluate_employment_C6()
    evaluate_collateral_C6()
    evaluate_history_C6()
    calculate_final_risk_C6()

def evaluate_dti_C6() -> None:
    """Brief description."""
    if WS_DTI_RATIO <= 20:
        WS_RISK_SCORE += 100
    elif WS_DTI_RATIO <= 30:
        WS_RISK_SCORE += 80
    elif WS_DTI_RATIO <= 40:
        WS_RISK_SCORE += 60
    elif WS_DTI_RATIO <= 50:
        WS_RISK_SCORE += 40
    else:
        WS_RISK_SCORE += 20

def evaluate_employment_C6() -> None:
    """Brief description."""
    if WS_EMPLOYMENT_YEARS >= 5:
        WS_RISK_SCORE += 100
    elif WS_EMPLOYMENT_YEARS >= 3:
        WS_RISK_SCORE += 80
    elif WS_EMPLOYMENT_YEARS >= 1:
        WS_RISK_SCORE += 60
    else:
        WS_RISK_SCORE += 30

def evaluate_collateral_C6() -> None:
    """Brief description."""
    loan_mortgage = False
    if loan_mortgage:
        WS_LTV_RATIO = (WS_LOAN_AMOUNT / WS_PROPERTY_VALUE) * 100
        if WS_LTV_RATIO <= 80:
            WS_RISK_SCORE += 100
            WS_PMI_REQUIRED = "N"
        else:
            WS_LTV_PENALTY = (WS_LTV_RATIO - 80) * 2
            WS_RISK_SCORE -= int(WS_LTV_PENALTY)
            WS_PMI_REQUIRED = "Y"
            calculate_pmi_C6()

