def check_activity_C10(ws_account_rec: AccountRecordC10) -> None:
    """Checks account activity and marks dormant if inactive."""
    ws_days_inactive: int = 0
    ws_process_date: Any = None

    ws_days_inactive = integer_of_date_C10(ws_process_date) - integer_of_date_C10(ws_account_rec.acct_last_activity)
    if ws_days_inactive > 365:
        ws_account_rec.acct_status = 'D'
        mark_dormant_C10(ws_account_rec)

def mark_dormant_C10(ws_account_rec: AccountRecordC10) -> None:
    """Marks an account as dormant."""
    ws_process_date: Any = None

    ws_account_rec.acct_status_desc = 'DORMANT'
    ws_account_rec.acct_dormant_date = ws_process_date
    rewrite_account_record_C10(ws_account_rec)
    send_dormant_notice_C10(ws_account_rec.acct_id)

