def escheatment_processing_C10() -> None:
    """Processes accounts for escheatment."""
    ws_eof_flag: str = 'N'

    while ws_eof_flag != 'Y':
        try:
            ws_account_rec = read_account_file_C10()
            if ws_account_rec.acct_status == 'D':
                check_escheatment_C10(ws_account_rec)
        except EOFError:
            ws_eof_flag = 'Y'

    ws_eof_flag = 'N'

def check_escheatment_C10(ws_account_rec: AccountRecordC10) -> None:
    """Checks if an account is eligible for escheatment."""
    ws_dormant_years: Decimal = Decimal('0')
    ws_process_date: Any = None
    ws_escheat_years: int = 0

    ws_dormant_years = (integer_of_date_C10(ws_process_date) - integer_of_date_C10(ws_account_rec.acct_dormant_date)) / 365
    if ws_dormant_years >= ws_escheat_years:
        escheat_account_C10(ws_account_rec)

def escheat_account_C10(ws_account_rec: AccountRecordC10) -> None:
    """Escheats an account."""
    ws_escheat_amount: Decimal = Decimal('0')
    ws_process_date: Any = None

    ws_account_rec.acct_status = 'E'
    ws_escheat_amount = ws_account_rec.acct_balance
    ws_account_rec.acct_balance = Decimal('0')
    create_escheat_record_C10(ws_account_rec, ws_escheat_amount, ws_process_date)
    rewrite_account_record_C10(ws_account_rec)

def create_escheat_record_C10(ws_account_rec: AccountRecordC10, ws_escheat_amount: Decimal, ws_process_date: Any) -> None:
    """Creates an escheat record."""
    ws_escheat_record = EscheatRecordC10()

    ws_escheat_record.escheat_account = ws_account_rec.acct_id
    ws_escheat_record.escheat_amount = ws_escheat_amount
    ws_escheat_record.escheat_date = ws_process_date
    ws_escheat_record.escheat_owner = ws_account_rec.acct_owner_name
    ws_escheat_record.escheat_address = ws_account_rec.acct_owner_address
    write_escheat_record_C10(ws_escheat_record)

