def optimize_funding_mix_C13() -> None:
    """Optimizes the funding mix."""
    ws_total_int_expense: Decimal = Decimal("50000.00")
    ws_total_deposits: Decimal = Decimal("1000000.00")
    ws_deposit_cost: Decimal = (ws_total_int_expense / ws_total_deposits) * Decimal("100.00")
