def _37325_find_ic_counterpart_C15() -> None:
    """Finds intercompany counterpart."""
    global WS_IC_IDX2C15, WS_IC_DIFFC15
    ws_search_from  = None  # TODO: was IC_FROM_ENTITYC15
    ws_search_to  = None  # TODO: was IC_TO_ENTITYC15
    WS_IC_IDX2C15 = 1
    while WS_IC_IDX2C15 <= WS_IC_COUNTC15:
        if IC_FROM_ENTITYC15 == ws_search_to:
            if IC_TO_ENTITYC15 == ws_search_from:
                WS_IC_DIFFC15 = IC_AMOUNTC15 + IC_AMOUNTC15
